import { createCompiler, instantiateGuest, type Guest } from "@mewhhaha/blot";
import { libraryUrl } from "../mod.ts";
import { blotRoot } from "../tools/setup.ts";
import { summary } from "../tools/report.ts";
export const root = new URL("../", import.meta.url);
export const path = (name: string) => new URL(name, root).pathname;
export const read = (name: string) => Deno.readTextFile(path(name));
export async function probe(name:string,fixture:string,variants:Record<string,string>[],calls:[string,number][],verify?:(a:Guest,b:Guest)=>void) {
 const compiler=await createCompiler({entry:new URL(fixture,root),imports:{"ink/":libraryUrl,"pen/":new URL("tests/fixtures/pen/",root)},executable:new URL("zig-native/zig-out/bin/blotc",blotRoot),stdRoot:new URL("std/",blotRoot),prelude:new URL("std/prelude.blot",blotRoot)});
 const guests:Guest[]=[];
 try {
  for (const sources of variants) {const built=await compiler.build({sources});if(!built.success)throw new Error(JSON.stringify(built.diagnostics));guests.push(await instantiateGuest(built.bytes));}
  verify?.(guests[0],guests[1]);
  const rows=[];
  for (const [entry,size] of calls) {
   const samples:number[][]=guests.map(()=>[]);const ratios:number[]=[];let witness;
   for(let round=0;round<40;round++){
    const values:unknown[]=[];const elapsed:number[]=[];
    for(let turn=0;turn<guests.length;turn++) {const at=(round+turn)%guests.length,start=performance.now();values[at]=guests[at].call(entry,size);elapsed[at]=performance.now()-start;if(round>=20)samples[at].push(elapsed[at]);}
    if(values.some(v=>JSON.stringify(v)!==JSON.stringify(values[0])))throw new Error(`Witness differs ${name} ${entry} ${size}: ${JSON.stringify(values)}`);
    if(round>=20 && elapsed.length>1)ratios.push(elapsed[1]/elapsed[0]);witness=values[0];
   }
   rows.push({entry,size,times:samples.map(summary),ratio:ratios.length?summary(ratios):null,bytes:guests.map(g=>g.memoryBytes()),witness});
  }
  const result={name,rows};console.log(JSON.stringify(result));return result;
 } catch(error) {const result={name,error:String(error)};console.log(JSON.stringify(result));return result;}
 finally {guests.forEach(g=>g.dispose());await compiler.dispose();}
}

