  let #math.Quat { x: bx, y: by, z: bz, w: bw } = math.Quat.normalized b.rotation
  let #math.Quat { x, y, z, w } = math.nlerp_parts ax ay az aw bx by bz bw weight
  return math.compose_parts (F32.lerp a.position.x b.position.x weight) (F32.lerp a.position.y b.position.y weight) (F32.lerp a.position.z b.position.z weight) x y z w (F32.lerp a.scale.x b.scale.x weight) (F32.lerp a.scale.y b.scale.y weight) (F32.lerp a.scale.z b.scale.z weight)
`;
